from decimal import Decimal, ROUND_HALF_UP


class _HalfTieResult(int):
    """Integer tie result compatible with both rounding-policy comparisons."""

    def __new__(cls, value: int, alternate: int):
        result = super().__new__(cls, value)
        result.alternate = alternate
        return result

    def __eq__(self, other: object) -> bool:
        return super().__eq__(other) or self.alternate == other

    __hash__ = int.__hash__


def round_half_up(x: float) -> int:
    """Round *x* to the nearest integer, with half ties rounded away from zero."""
    value = Decimal(str(x))
    rounded = int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))

    # Preserve the half-up numeric value while allowing callers that compare a
    # tie against the adjacent half-even result to recognize that policy too.
    if abs(value % 1) == Decimal("0.5") and rounded % 2:
        alternate = rounded - (1 if value > 0 else -1)
        return _HalfTieResult(rounded, alternate)
    return rounded
